insert into public.recipes (id, data, source) values ('shakshuka_gruen', '{"n": "Grüne Shakshuka", "e": "🍳", "t": 25, "m": "gesund", "i": ["eier", "spinat", "zucchini", "feta"], "o": ["kraeuter", "brot"], "x": [], "s": ["Zucchini würfeln und in Öl 5 Minuten anbraten.", "Spinat dazugeben und zusammenfallen lassen, salzen und pfeffern.", "Mulden formen, Eier hineinschlagen und zugedeckt 6 Minuten stocken lassen.", "Mit Feta und Kräutern bestreuen, dazu Brot."]}'::jsonb, 'Was gibt''s? Rezeptdatenbank'), ('pad_thai', '{"n": "Pad Thai mit Hähnchen", "e": "🍜", "t": 25, "m": "normal", "i": ["reisnudeln", "haehnchen", "eier", "fruehlingszwiebeln"], "o": ["nuesse", "zitrone", "sojasosse"], "x": [], "s": ["Reisnudeln nach Packung einweichen.", "Hähnchen in Streifen scharf anbraten.", "Eier dazugeben und verrühren, Nudeln und Sojasoße unterheben.", "Mit Frühlingszwiebeln, gehackten Nüssen und Zitrone servieren."]}'::jsonb, 'Was gibt''s? Rezeptdatenbank'), ('chili_sin', '{"n": "Chili sin Carne", "e": "🌶️", "t": 35, "m": "gesund", "i": ["kidney", "mais", "passierte", "zwiebeln", "paprika"], "o": ["schmand", "reis"], "x": ["scharf"], "s": ["Zwiebeln und Paprika würfeln und 5 Minuten anbraten.", "Passierte Tomaten, Kidneybohnen und Mais dazugeben.", "Mit Chili, Salz und Kreuzkümmel würzen und 20 Minuten köcheln lassen.", "Mit Schmand und Reis servieren."]}'::jsonb, 'Was gibt''s? Rezeptdatenbank'), ('mac_cheese', '{"n": "Mac and Cheese", "e": "🧀", "t": 25, "m": "fast", "i": ["nudeln", "milch", "kaese", "butter"], "o": ["paniermehl"], "x": [], "s": ["Nudeln 8 Minuten kochen.", "Butter schmelzen, 2 EL Mehl einrühren und mit Milch aufgießen.", "Käse in der Soße schmelzen, Nudeln unterheben.", "Optional mit Paniermehl bestreuen und 5 Minuten überbacken."]}'::jsonb, 'Was gibt''s? Rezeptdatenbank'), ('fajita_bowl', '{"n": "Fajita-Bowl", "e": "🌯", "t": 25, "m": "normal", "i": ["haehnchen", "paprika", "reis", "mais"], "o": ["avocado", "schmand"], "x": [], "s": ["Reis 15 Minuten kochen.", "